"use client";

import CountUp from "@/components/CountUp";
import GradientText from "@/components/GradientText";
import { useTranslations } from "next-intl";
import dynamic from "next/dynamic";
import localFont from "next/font/local";
import { useEffect, useMemo, useState } from "react";
import Image from "next/image";

// const alice = localFont({ src: 'Pixeboy.ttf' })

export default function Home() {
  const t = useTranslations("Home");
    const texts = ["First option", "Second option", "Third option"];
  const [index, setIndex] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setIndex((prevIndex) => (prevIndex + 1) % texts.length);
    }, 2000);

    return () => clearInterval(interval); 
  }, []);
  
  const Map = dynamic(() => import("@/components/Map"), {
    ssr: false,
  });

  const numDays = useMemo(() => {
    const currentDate = new Date();
    const end = new Date("2026-11-21");

    let utc1 = Date.UTC(
      currentDate.getFullYear(),
      currentDate.getMonth(),
      currentDate.getDate()
    );
    let utc2 = Date.UTC(end.getFullYear(), end.getMonth(), end.getDate());
    const timeDiff = Math.abs(utc2 - utc1);
    return Math.ceil(timeDiff / (1000 * 60 * 60 * 24));
  }, []);

  return (
    <div className="app">
      <div className="card">
        <img
          src="/border.webp"
          style={{
            transform: "scaleX(-1) rotate(90deg)",
          }}
          className="border"
        />
        <img
          src="/border.webp"
          style={{
            transform: "scaleY(-1) scaleX(-1) rotate(270deg)",
            right: 0,
          }}
          className="border"
        />
        <img
          src="/border.webp"
          style={{ transform: "scaleY(1) rotate(270deg)", bottom: 0 }}
          className="border"
        />
        <img
          src="/border.webp"
          style={{
            transform: "scaleY(1) scaleX(-1) rotate(270deg)",
            bottom: 0,
            right: 0,
          }}
          className="border"
        />

        <span style={{ fontSize: "5rem" }}>{texts[index]}</span>
      </div>

      <div className="card">
        <Map position={[-34.374077, -58.72908]} zoom={13} height={"40em"}></Map>
      </div>
      <div className="card">
        <span style={{ fontSize: "5rem" }}>{t("see_you")}</span>
        <GradientText
          colors={["#8aaf7c", "#51627b", "#54654e", "#7ea0d3", "#8aaf7c"]}
          animationSpeed={3}
          showBorder={false}
          className="counter"
        >
          <CountUp direction="down" from={numDays} to={365} />
        </GradientText>
        <span style={{ fontSize: "5rem" }}>{t("days")}</span>
      </div>
    </div>
  );
}
